package ai.eva.android.probe;
import java.io.*;import java.nio.file.*;
public final class DocumentPreviewTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{File root=new File(args[0]);String word=DocumentPreview.renderOffice(new File(root,"sample.docx"));check(word.contains("<h1>")&&word.contains("课程预览"),"word heading");check(word.contains("font-weight:bold"),"word bold");check(word.contains("<table>"),"word table");check(word.contains("data:image/png;base64,"),"embedded image");check(word.contains("&lt;script&gt;"),"word text escaped");Files.write(new File(root,"word-preview.html").toPath(),DocumentPreview.page(word,false).getBytes("UTF-8"));
 String excel=DocumentPreview.renderOffice(new File(root,"sample.xlsx"));check(excel.contains("课程预算"),"sheet names");check(excel.indexOf("预算</td>")<excel.indexOf("第二页内容"),"workbook relationship order and absolute targets");check(excel.contains("=SUM(B1)"),"uncached formula retained");check(excel.contains("&lt;img src=x&gt;"),"shared strings escaped");check(excel.contains("<th>B</th>"),"column heading");Files.write(new File(root,"excel-preview.html").toPath(),DocumentPreview.page(excel,false).getBytes("UTF-8"));
 String ppt=DocumentPreview.renderOffice(new File(root,"sample.pptx"));check(ppt.indexOf("第一张幻灯片")<ppt.indexOf("第二张幻灯片"),"presentation relationship order");check(ppt.contains("viewBox=\"0 0 960.0 540.0\""),"slide dimensions");check(ppt.contains("foreignObject"),"slide positioned text");Files.write(new File(root,"ppt-preview.html").toPath(),DocumentPreview.page(ppt,false).getBytes("UTF-8"));
 for(String name:new String[]{"unsafe.docx","bomb.docx"}){boolean rejected=false;try{DocumentPreview.renderOffice(new File(root,name));}catch(Exception e){rejected=true;}check(rejected,"reject "+name);}
 check(DocumentPreview.packagePath("word/","../media/a.png").equals("media/a.png"),"internal package relative target");boolean rejected=false;try{DocumentPreview.packagePath("word/","../../secret");}catch(IOException e){rejected=true;}check(rejected,"reject external package traversal");check(DocumentPreview.page("sample",false).contains("connect-src 'none'"),"preview blocks outbound requests");check(DocumentPreview.kind(new File("test.docx")).equals("office"),"office route");check(DocumentPreview.kind(new File("test.md")).equals("markdown"),"markdown route");check(DocumentPreview.kind(new File("test.html")).equals("html"),"html route");check(DocumentPreview.kind(new File("test.wav")).equals("audio"),"audio route");check(DocumentPreview.kind(new File("test.webm")).equals("video"),"video route");check(DocumentPreview.kind(new File("test.doc")).equals("unsupported"),"legacy binary not misrepresented");System.out.println("PASS "+checks+" document preview contracts");}
}
